comments.body:
Fallbacking to /dev/tty in case a ttyname can't be found would make it work for both fzf and fzf --tmux.

```diff
diff -ru ./src/tui/light_unix.go b/src/tui/light_unix.go
--- ./src/tui/light_unix.go	1969-12-31 19:00:01.000000000 -0500
+++ b/src/tui/light_unix.go	2025-04-13 11:07:53.380319509 -0400
@@ -43,14 +43,14 @@
 }

 func openTty(mode int) (*os.File, error) {
+	tty := ttyname()
+	if len(tty) > 0 {
+		if in, err := os.OpenFile(tty, mode, 0); err == nil && util.IsTty(in) {
+			return in, nil
+		}
+	}
 	in, err := os.OpenFile(consoleDevice, mode, 0)
 	if err != nil {
-		tty := ttyname()
-		if len(tty) > 0 {
-			if in, err := os.OpenFile(tty, mode, 0); err == nil {
-				return in, nil
-			}
-		}
 		return nil, errors.New("failed to open " + consoleDevice)
 	}
 	return in, nil
diff -ru ./test/test_exec.rb b/test/test_exec.rb
--- ./test/test_exec.rb	1969-12-31 19:00:01.000000000 -0500
+++ b/test/test_exec.rb	2025-04-13 14:23:10.215855096 -0400
@@ -380,7 +380,7 @@
   end

   def test_become_tty
-    tmux.send_keys "sleep 0.5 | #{FZF} --bind 'start:reload:ls' --bind 'load:become:tty'", :Enter
+    tmux.send_keys "sleep 0.5 | #{FZF} --bind 'start:reload:ls' --bind 'load:become:tty' 2>/dev/null", :Enter
     tmux.until { |lines| assert_includes lines, '/dev/tty' }
   end
```
